css:
.like-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: relative;
}

.like-btn input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.like-btn svg {
  width: 3rem;
  height: 3rem;
  fill: #000000;
  padding: 10px;
  transition: 0.2s ease all;
}

#icon-like-regular {
  display: block;
}

#icon-like-solid {
  display: none;
}

#like-checkbox:checked ~ #icon-like-regular {
  display: none;
  animation: checked-icon-like 0.5s;
}

#like-checkbox:checked ~ #icon-like-solid {
  display: block;
  fill: #d7000f;
  animation: checked-icon-like 0.5s;
}

.fireworks {
  transform: scale(0.4);
}

#like-checkbox:checked ~ .fireworks > .checked-like-fx {
  position: absolute;
  width: 10px;
  height: 10px;
  right: 40px;
  border-radius: 50%;
  box-shadow:
    0 0 #fff,
    0 0 #fff,
